mapper.select:
SELECT COUNT(*)
FROM shopion.tOrdOrderChangeNo
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}

SELECT IFNULL(MAX(OrderChangeNo), 0)
FROM shopion.tOrdOrderChangeNo
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}

SELECT OrderChangeNo
FROM shopion.tOrdOrderChangeNo
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
ORDER BY OrderChangeNo DESC
LIMIT 1

mapper.insert:
INSERT INTO shopion.tOrdOrderChangeNo (
    OrderNo, OrderProdNo, OrderChangeNo, PrevState,
    State, RegistId, RegistName, RegistDate
)
SELECT
    OP.OrderNo, OP.OrderProdNo, #{orderChangeNo}, OP.OrderState,
    1, #{registId}, #{registName}, NOW()
FROM shopion.tOrdOrderProd OP
WHERE OP.OrderNo = #{orderNo}
AND OP.OrderProdNo = #{orderProdNo}
